import type { AstroConfig, AstroIntegration } from 'astro';
import { cp, mkdir, readFile, rm, writeFile } from 'node:fs/promises';
import { transpileModule, ModuleKind, ScriptTarget } from 'typescript';
import { defaultLocale, locales, type Locale } from '../../src/i18n/config';

// Build Output API packages a root-only middleware alongside static Astro pages.
// Availability comes from the pages actually generated by the content registry.
export default function vercelLanguage(): AstroIntegration {
	let config: AstroConfig;
	return {
		name: 'wortise-vercel-language',
		hooks: {
			'astro:config:done': ({ config: resolved }) => { config = resolved; },
			'astro:build:done': async ({ dir, pages, logger }) => {
				if (config.output !== 'static') throw new Error('Language routing expects a static site.');
				const basePath = `${config.base.replace(/\/+$/, '')}/`;
				const paths = new Set(pages.map(({ pathname }) => pathname.replace(/^\/+|\/+$/g, '')));
				const homes: Partial<Record<Locale, string>> = {};
				for (const locale of locales) {
					if (paths.has(locale) || paths.has(`${basePath}${locale}`.replace(/^\//, ''))) homes[locale] = `${basePath}${locale}/`;
				}
				if (!homes[defaultLocale]) throw new Error('The default locale must have a published home page.');
				const output = new URL('.vercel/output/', config.root);
				await rm(output, { recursive: true, force: true });
				const middleware = new URL('functions/language.func/', output);
				await mkdir(middleware, { recursive: true });
				await cp(dir, new URL(`static/${basePath.slice(1)}`, output), { recursive: true });
				for (const name of ['config', 'negotiation']) {
					const source = await readFile(new URL(`../../src/i18n/${name}.ts`, import.meta.url), 'utf8');
					const { outputText } = transpileModule(source, { compilerOptions: { module: ModuleKind.ESNext, target: ScriptTarget.ES2022 } });
					await writeFile(new URL(`${name}.js`, middleware), outputText);
				}
				await writeFile(new URL('index.js', middleware), `import { languageRedirect } from './negotiation.js';\nexport default request => languageRedirect(request, ${JSON.stringify({ basePath, homes })});\n`);
				await writeFile(new URL('.vc-config.json', middleware), JSON.stringify({ runtime: 'edge', entrypoint: 'index.js' }));
				const escapedBase = basePath.replace(/[.*+?^${}()|[\]\\]/g, '\\$&');
				await writeFile(new URL('config.json', output), JSON.stringify({
					version: 3,
					routes: [
						{ src: `^${escapedBase}$`, methods: ['GET', 'HEAD'], middlewarePath: 'language', continue: true },
						{ src: `^${escapedBase}_astro/.*$`, headers: { 'Cache-Control': 'public, max-age=31536000, immutable' }, continue: true },
						{ handle: 'filesystem' },
					],
				}, null, 2));
				logger.info(`Vercel static output ready; automatic languages: ${Object.keys(homes).join(', ')}.`);
			},
		},
	};
}
